"""Subset Sum — reachable sums as a bitset.

Each value shifts the set of reachable sums left by its own size; bit `target`
answers the question.

Time: O(n * target / 64)   Space: O(target)
"""
from typing import List


class Solution:
    def isSubsetSum(self, nums: List[int], target: int) -> bool:
        reachable = 1
        for value in nums:
            reachable |= reachable << value
        return bool((reachable >> target) & 1)
